async function authenticate(register) {
  if (register && !termsAccepted) { setError('Please read and agree to the Terms & Conditions before creating your account.'); return; }
  if (register && role==='worker' && !nationalInsuranceNumber.trim() && !workerPermitNumber.trim()) { setError('Enter your National Insurance number or worker permit number so hyrz can prevent blocked-account re-registration.'); return; }
  if (register && password !== confirmPassword) {
    setError('Your passwords do not match. Please try again.');
    return;
  }

  await action(async () => {
    const d = await request(register ? '/auth/register' : '/auth/login', {
      method: 'POST',
      body: JSON.stringify({
        email,
        password,
        confirmPassword,
        role,
        firstName,
        lastName,
        businessName,
        companyRole,
        companyNumber,
        businessAddress: role==='employer' ? businessAddress.trim() : undefined,
        businessCity: role==='employer' ? businessCity.trim() : undefined,
        postcode: role==='employer' ? businessPostcode.trim() : undefined,
        nationalInsuranceNumber: register && role==='worker' ? nationalInsuranceNumber.trim() : undefined,
        workerPermitNumber: register && role==='worker' ? workerPermitNumber.trim() : undefined,
        termsAccepted: register ? termsAccepted : undefined,
        termsVersion: register ? '2026-10-19' : undefined
      })
    });

    if (register) {
      setNotice('Your account has been created. Check your inbox to verify your email.');
      navigateTo('checkEmail');
      return;
    }

    localStorage.setItem('hyrz_token', d.token);
    setUser(d.user);
    await load();
    setPageHistory([]);setPage(d.user?.role==='admin'?'admin':d.user?.role==='worker'?'jobs':'dashboard');
  });
}

async function requestPasswordReset(e){
 e?.preventDefault?.();
 const address=String(email||'').trim();
 if(!address){setError('Enter your email address first.');return;}
 await action(async()=>{
  const result=await request('/auth/password-reset/request',{method:'POST',body:JSON.stringify({email:address})});
  setNotice(result.message||'If an active account exists for that email, a password reset link will be sent.');
  navigateTo('passwordResetSent');
 });
}

async function submitPasswordReset(e){
 e?.preventDefault?.();
 if(resetPasswordValue.length<12){setError('Choose a password of at least 12 characters.');return;}
 if(resetPasswordValue!==resetPasswordConfirm){setError('Your new passwords do not match.');return;}
 await action(async()=>{
  const result=await request('/auth/password-reset/confirm',{method:'POST',body:JSON.stringify({token:passwordResetToken,newPassword:resetPasswordValue})});
  localStorage.removeItem('hyrz_token');
  setPasswordResetToken('');setResetPasswordValue('');setResetPasswordConfirm('');
  setNotice(result.message||'Your password has been reset. You can now sign in.');
  navigateTo('login');
 });
}

 async function persistShiftTemplate(name, source=shift, requirements=shiftRequirements, perks=shiftPerks, preferences=shiftPreferences, start=postStartTime, end=postEndTime){
  const cleanName=String(name||'').trim();
  if(!cleanName){setError('Give this shift template a name.');return false;}
  // Preserve every reusable shift field, excluding only dates and worker count.
  const reusableShift={...(source||{})};
  ['slots','workers','numberOfWorkers','dates','postDates','startsAt','endsAt','startDate','endDate'].forEach(key=>delete reusableShift[key]);
  const payload={
    name:cleanName,
    shift:{
      ...reusableShift,
      title:String(source?.title||'').trim(),
      shiftType:String(source?.shiftType||'').trim(),
      hourlyPay:String(source?.hourlyPay??''),
      description:String(source?.description||''),
      additionalNotes:String(source?.additionalNotes||'')
    },
    requirements:(Array.isArray(requirements)?requirements:[]).map(x=>String(x||'').trim()).filter(Boolean),
    perks:(Array.isArray(perks)?perks:[]).map(x=>String(x||'').trim()).filter(Boolean),
    preferences:(Array.isArray(preferences)?preferences:[]).map(x=>String(x||'').trim()).filter(Boolean),
    autoAcceptEnabled:Boolean(source?.autoAcceptEnabled??autoAcceptEnabled),
    autoAcceptCriteria:{...(source?.autoAcceptCriteria||autoAcceptCriteria)},
    startTime:start,
    endTime:end
  };
  try{
    const result=await request('/shift-templates',{method:'POST',body:JSON.stringify(payload)});
    const saved=result.template;
    setShiftTemplates(current=>[saved,...current.filter(item=>Number(item.id)!==Number(saved.id))]);
    setNotice('Template saved');
    return saved;
  }catch(error){setError(error.message||'Could not save the shift template.');return false;}
 }
 function restoreShiftTemplate(item){
   const savedShift=item?.shift&&typeof item.shift==='object'?item.shift:{};
   const reusable={...savedShift};
   ['slots','workers','numberOfWorkers','dates','postDates','startsAt','endsAt','startDate','endDate'].forEach(key=>delete reusable[key]);
   setShift(current=>({...current,...reusable,title:savedShift.title||'',description:savedShift.description||'',additionalNotes:savedShift.additionalNotes||'',shiftType:savedShift.shiftType||'hospitality',hourlyPay:String(savedShift.hourlyPay??15),slots:1,startsAt:'',endsAt:''}));
   setShiftRequirements(Array.isArray(item?.requirements)?(item.requirements.length?item.requirements:['']):['']);
   setShiftPerks(Array.isArray(item?.perks)?(item.perks.length?item.perks:['']):['']);
   setShiftPreferences(Array.isArray(item?.preferences)?(item.preferences.length?item.preferences:['']):['']);
   setAutoAcceptEnabled(Boolean(item?.autoAcceptEnabled));
   setAutoAcceptCriteria({requirements:true,favourites:false,highRating:false,cancellation24h:false,...(item?.autoAcceptCriteria||{})});
   setPostStartTime(item?.startTime||'09:00');setPostEndTime(item?.endTime||'17:00');
   setPostDates([]);setShiftValidation({});setError('');
  }
  function applyTemplateToCurrentShift(item){restoreShiftTemplate(item);setTemplateName('');setTemplateSetupOpen(false);setUseTemplateOpen(false);setNotice('Template loaded. Choose the dates and worker count, then publish.');}
  function useShiftTemplate(item){restoreShiftTemplate(item);setTemplateName(item?.name||'');setShiftSection('new');setShiftCluster([]);navigateTo('post');}
  async function deleteShiftTemplate(id){
  const template=shiftTemplates.find(item=>Number(item.id)===Number(id));
  if(!window.confirm('Delete the template'+(template?.name?' “'+template.name+'”':'')+'? This cannot be undone.'))return;
  try{await request('/shift-templates/'+id,{method:'DELETE'});setShiftTemplates(current=>current.filter(item=>Number(item.id)!==Number(id)));setNotice('Template deleted.');}
  catch(error){setError(error.message||'Could not delete the shift template.');}
 }
 async function savePublishedShiftAsTemplate(item){
  const starts=new Date(item.starts_at),ends=new Date(item.ends_at);
  const time=value=>String(value.getHours()).padStart(2,'0')+':'+String(value.getMinutes()).padStart(2,'0');
  const source={title:item.title||'',description:item.description||'',additionalNotes:item.additional_notes||item.additionalNotes||'',shiftType:item.shift_type||item.shiftType||'hospitality',hourlyPay:String(item.hourly_pay??item.hourlyPay??15)};
  const suggested=String(item.title||'Shift')+' template';
  const name=window.prompt('Name this shift template:',suggested);
  if(name===null)return;
  await persistShiftTemplate(name,source,item.requirements||[],item.perks||[],item.preferences||[],time(starts),time(ends));
 }
