async function apply(id){const target=shifts.find(item=>Number(item.id)===Number(id));if(!target)return;setApplicationReviewMode('apply');setApplicationRequirementChecks([]);setApplicationPreferenceChecks([]);setApplicationContractAccepted(false);setApplicationShowAllCompanyShifts(false);setApplicationSelectedShiftIds([Number(id)]);setApplicationConfirmShiftId(Number(id));} async function submitApplication(ids,requirements,preferences){const selectedIds=(Array.isArray(ids)?ids:[ids]).map(Number).filter((id,index,all)=>Number.isFinite(id)&&all.indexOf(id)===index);if(!applicationContractAccepted){setError('Please agree to the shift contracts before submitting your applications.');return;}if(!selectedIds.length){setError('Please select at least one shift to apply for.');return;}await action(async()=>{for(const id of selectedIds){const target=shifts.find(item=>Number(item.id)===id);await request(`/shifts/${id}/apply`,{method:'POST',body:JSON.stringify({confirmedRequirements:requirements.length>0,confirmedPreferences:preferences,contractAccepted:true,contractSnapshot:target?JSON.stringify(buildShiftContract(target)):''})});const privateOffer=privateOffers.find(offer=>Number(offer.id)===id);if(privateOffer)await request('/private-offers/'+privateOffer.offer_id+'/respond',{method:'POST',body:JSON.stringify({status:'accepted'})});}setApplicationConfirmShiftId(null);setApplicationSelectedShiftIds([]);setApplicationContractAccepted(false);setNotice(selectedIds.length===1?'Application submitted':`Applications submitted for ${selectedIds.length} shifts`);await load()})} async function updateApplication(id,status){await action(async()=>{const result=await request(`/applications/${id}`,{method:'PATCH',body:JSON.stringify({status})});if(result.confirmationRequired)setNotice('Confirmation request sent to the worker. The position will only be allocated if they confirm.');await load()})}
