    {!workchatOpenId&&workchatSection==='current'&&<><div className="workchat-list">{workchatItems.filter(w=>w.status==='current'&&[w.name,w.company_name,w.business_name,w.employer_name,w.employer_company_name,w.created_by_name,w.last_message].filter(Boolean).join(' ').toLowerCase().includes(workchatListSearch.trim().toLowerCase())).length?workchatItems.filter(w=>w.status==='current'&&[w.name,w.company_name,w.business_name,w.employer_name,w.employer_company_name,w.created_by_name,w.last_message].filter(Boolean).join(' ').toLowerCase().includes(workchatListSearch.trim().toLowerCase())).sort((a,b)=>Number((Number(b.unread_count)||0)>0)-Number((Number(a.unread_count)||0)>0)||(Number(b.unread_count)||0)-(Number(a.unread_count)||0)||(new Date(b.last_message_at||b.created_at||0).getTime()-new Date(a.last_message_at||a.created_at||0).getTime())).map(w=><button type="button" className="workchat-wa-row" key={w.id} aria-label={'Open workchat '+w.name} onClick={()=>{setWorkchatOpenId(Number(w.id));setWorkchatSection('current');setWorkchatSettingsOpen(false);}}><span className="workchat-wa-avatar">{workchatAvatar(w)?<img src={workchatAvatar(w)} alt=""/>:<b>{workchatInitials(w.name)}</b>}</span><span className="workchat-wa-copy"><strong>{w.name||'Workchat'}</strong><small>{w.last_message?(<><b>{Number(w.last_message_sender_id??w.last_sender_id)===Number(user?.id)?'You':w.last_message_sender_name||w.last_sender_name||'Latest message'}:</b> {w.last_message}{Number(w.last_message_sender_id??w.last_sender_id)===Number(user?.id)&&<span className={'direct-read-ticks'+(Number(w.last_message_recipient_count)>0&&Number(w.last_message_read_count)>=Number(w.last_message_recipient_count)?' is-read':'')}> ✓✓</span>}</>):'No messages yet'}</small></span><span className="workchat-wa-meta"><time>{w.last_message_at?new Date(w.last_message_at).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'}):w.created_at?new Date(w.created_at).toLocaleDateString('en-GB',{day:'numeric',month:'short'}):''}</time>{Number(w.unread_count||0)>0&&<b className="workchat-unread-count">{Number(w.unread_count)>99?'99+':Number(w.unread_count)}</b>}<small>{w.participant_count??w.participants?.length??0} members</small></span></button>):<div className="empty-state">{workchatUnreadFilter==='all'?'No current workchats yet. Choose “New workchat +” to create one.':workchatUnreadFilter==='messages'?'You have no unread messages.':'You have no unread workchats.'}</div>}</div></>}
    {!workchatOpenId&&workchatSection==='past'&&<div className="workchat-list">{workchatItems.filter(w=>w.status==='past').length?workchatItems.filter(w=>w.status==='past').map(w=><article className="workchat-item workchat-item-clickable workchat-item-minimal" key={w.id} role="button" tabIndex={0} aria-label={'Open workchat '+w.name} onClick={()=>{setWorkchatOpenId(Number(w.id));setWorkchatSettingsOpen(false);}} onKeyDown={e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();setWorkchatOpenId(Number(w.id));setWorkchatSettingsOpen(false);}}}><div className="workchat-item-avatar">{workchatAvatar(w)?<img src={workchatAvatar(w)} alt="" />:<span>{workchatInitials(w.name)}</span>}</div><div className="workchat-item-copy"><strong>{w.name}</strong><small>{w.participant_count??w.participants?.length??0} participants</small></div><button type="button" className="secondary" onClick={e=>{e.stopPropagation();action(async()=>{await request('/workchats/'+w.id+'/status',{method:'PATCH',body:JSON.stringify({status:'current'})});setWorkchatRefresh(v=>v+1);});}}>Restore</button></article>):<div className="empty-state">Disabled workchats will appear here.</div>}</div>}
