 {user?.role==='employer'&&page==='contact'&&<><div className="workchat-back-row"><button type="button" className="secondary icon-back-button" aria-label="Go back" title="Go back" onClick={goBack}><svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M9 14 4 9l5-5"/><path d="M4 9h9a7 7 0 0 1 7 7v4"/></svg></button></div><section className="panel employer-contact" style={{width:'100%',maxWidth:'900px',boxSizing:'border-box',margin:'0 auto',textAlign:'center'}}><span className="eyebrow">WE'RE HERE TO HELP</span><h2>Contact hyrz</h2><p style={{maxWidth:'680px',margin:'0 auto 1.25rem'}}>You can contact the hyrz support team here or in your inbox section with messages relating to an enquiry, a complaint or a checkout dispute. When you send a message, hyrz admins will receive both an email and an in-app notification so they can review it. We'll respond as soon as possible. Please keep an eye on your inbox and/or email for responses.</p><div style={{maxWidth:'540px',width:'100%',margin:'0 auto',textAlign:'left'}}><SupportContact user={user} action={action} busy={busy} setNotice={setNotice} setError={setError}/></div></section></>}

