  'admin.created':'Created an administrator account','admin.tier_changed':'Changed an administrator’s tier','admin.deletion_requested':'Requested administrator access removal','admin.password_changed':'Changed an administrator password',
  'invoice.adhoc_created':'Created an additional invoice','invoice.reminder_sent':'Sent an invoice reminder','invoice.status_changed':'Changed an invoice status','invoice.adhoc_voided':'Voided an additional invoice',
  'dispute.assigned':'Assigned a checkout dispute','dispute.resolved':'Resolved a checkout dispute','dispute.opened':'Opened a checkout dispute',
