  'shift.created':'Created a shift','shift.cancelled':'Cancelled a shift','application.approved_worker_removed':'Removed an approved worker from a shift','application.cancelled':'Cancelled a shift application','application.approved':'Approved a shift application','worker.no_show_recorded':'Recorded a worker no-show',
  'checkout.submitted':'Submitted a checkout','checkout.counter_offer_submitted':'Submitted a checkout counter-offer','checkout.approved':'Approved a checkout','checkout.disputed':'Marked a checkout as disputed',
