function WorkerTimetable({applications,navigateTo}) {
 const [selectedDate,setSelectedDate]=useState('');
 const today=new Date();today.setHours(0,0,0,0);
 const dates=Array.from({length:42},(_,i)=>{const d=new Date(today);d.setDate(today.getDate()+i);return d;});
 const keyFor=d=>d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
 const shifts=applications.filter(a=>['approved','accepted','confirmed'].includes(String(a.status||'').toLowerCase()));
 const shiftsByDate=shifts.reduce((acc,a)=>{const key=String(a.starts_at||'').slice(0,10);if(key){(acc[key]||(acc[key]=[])).push(a);}return acc;},{});
 const selectedShifts=shiftsByDate[selectedDate]||[];
 return <section className="panel worker-timetable-panel"><h2>Your timetable</h2><p>Your next six weeks. Orange dates have confirmed shifts; white dates are currently free.</p><div className="timetable-legend"><span><i className="timetable-legend-orange"/> Confirmed shift</span><span><i className="timetable-legend-white"/> Free</span></div><div className="timetable-grid"><div className="timetable-weekdays">{['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(day=><strong key={day}>{day}</strong>)}</div><div className="timetable-days">{dates.map(d=>{const key=keyFor(d),dayShifts=shiftsByDate[key]||[],occupied=dayShifts.length>0;return <button type="button" key={key} className={'timetable-day '+(occupied?'has-shift':'free-day')+(selectedDate===key?' selected':'')} aria-pressed={selectedDate===key} onClick={()=>setSelectedDate(key)}><small>{d.toLocaleDateString('en-GB',{month:'short'})}</small><strong>{d.getDate()}</strong>{occupied&&<span>{dayShifts.length} shift{dayShifts.length===1?'':'s'}</span>}</button>;})}</div></div>{selectedDate&&<section className="timetable-selected-shifts"><h3>{new Date(selectedDate+'T12:00:00').toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</h3>{selectedShifts.length===0?<div className="empty-state">You're currently free on this date. No confirmed shifts are listed.</div>:selectedShifts.map(a=><article className="timetable-shift-card" key={a.id}><h4>{a.title||'Shift'}</h4><p><strong>Employer:</strong> {a.business_name||'Not provided'}</p><p><strong>Location:</strong> {a.location||'Not provided'}</p><p><strong>Time:</strong> {a.starts_at?new Date(a.starts_at).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'}):'TBC'} – {a.ends_at?new Date(a.ends_at).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'}):'TBC'}</p>{a.hourly_pay!=null&&<p><strong>Hourly pay:</strong> £{Number(a.hourly_pay).toFixed(2)}</p>}<small>Status: {a.status}</small></article>)}</section>}</section>;
}

function WorkerEmployerFavourites({navigateTo,action,busy,setError,setNotice}) {
 const [tab,setTab]=useState('search');
 const [query,setQuery]=useState('');
 const [role,setRole]=useState('');
 const [location,setLocation]=useState('');
 const [results,setResults]=useState([]);
 const [favourites,setFavourites]=useState([]);
 const [myFavourites,setMyFavourites]=useState([]);
 const [loading,setLoading]=useState(false);
 async function loadSearch(past=false){setLoading(true);try{const params=new URLSearchParams();if(query.trim())params.set('q',query.trim());if(role.trim())params.set('role',role.trim());if(location.trim())params.set('location',location.trim());if(past)params.set('past','1');const r=await request('/worker/employers/search?'+params.toString());setResults(r.employers||[]);}catch(e){setError(e.message);}finally{setLoading(false);}}
 async function loadFavourites(){setLoading(true);try{const r=await request('/worker/employers/favourited-me');setFavourites(r.employers||[]);}catch(e){setError(e.message);}finally{setLoading(false);}}
 async function loadMyFavourites(){setLoading(true);try{const r=await request('/worker/employers/favourites');setMyFavourites(r.employers||[]);}catch(e){setError(e.message);}finally{setLoading(false);}}
 useEffect(()=>{if(tab==='search')loadSearch(false);else if(tab==='previous')loadSearch(true);else if(tab==='mine')loadMyFavourites();else loadFavourites();},[tab]);
 useEffect(()=>{if(tab!=='search')return;const timer=setTimeout(()=>loadSearch(false),250);return()=>clearTimeout(timer);},[query,role,location,tab]);
 async function toggleFavourite(employer){const next=!Boolean(employer.isFavourite);await action(async()=>{await request('/worker/employers/'+employer.business_id+'/favourite',{method:next?'POST':'DELETE',...(next?{body:JSON.stringify({})}:{})});const update=list=>list.map(item=>Number(item.business_id)===Number(employer.business_id)?{...item,isFavourite:next}:item);setResults(update);setFavourites(update);setMyFavourites(update);setNotice(next?'Employer added to your favourites.':'Employer removed from your favourites.');});}
 const items=tab==='favourites'?favourites:tab==='mine'?myFavourites:results;
 return <section className="panel worker-employer-favourites"><h2>Favourites</h2><p>Find employers, revisit previous employers, and see which employers have added you to their favourites.</p><div className="job-tabs">{[['search','Search employer'],['previous','Previous employers'],['mine','My favourites'],['favourites','On their favourites']].map(([id,label])=><button type="button" key={id} className={tab===id?'active':''} onClick={()=>setTab(id)}>{label}</button>)}</div>
 {tab==='search'&&<form className="employer-search-filters" onSubmit={e=>{e.preventDefault();loadSearch(false);}}><label>Company name<input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search company name"/></label><label>Available or past role<input value={role} onChange={e=>setRole(e.target.value)} placeholder="e.g. Bartender, Warehouse Operative"/></label><label>Location<input value={location} onChange={e=>setLocation(e.target.value)} placeholder="Town, city or postcode"/></label><button className="primary" disabled={loading}>Search employers</button></form>}
 {tab==='previous'&&<div><p className="muted">Employers you've applied to for shifts are shown here. Where shift history is available, roles from those employers are included.</p><form className="employer-search-filters" onSubmit={e=>{e.preventDefault();loadSearch(true);}}><label>Company name<input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Filter previous employers"/></label><label>Role worked or applied for<input value={role} onChange={e=>setRole(e.target.value)} placeholder="Filter by role"/></label><label>Location<input value={location} onChange={e=>setLocation(e.target.value)} placeholder="Filter by location"/></label><button className="primary" disabled={loading}>Search previous employers</button></form></div>}
 {loading?<p className="muted">Searching employers…</p>:items.length===0?<div className="empty-state">{tab==='favourites'?'No employers have added you to their favourites yet.':tab==='mine'?'You haven’t added any employers to your favourites yet. Search for employers and add them here.':tab==='previous'?'No previous employers match those filters.':'No employers match those search filters.'}</div>:<div className="employer-favourite-results">{items.map(employer=><article className="shiftrow shift-card" key={employer.business_id}><div className="shift-employer-avatar">{(employer.profile_picture||employer.employer_profile_picture||employer.logo_url)?<img src={employer.profile_picture||employer.employer_profile_picture||employer.logo_url} alt={employer.company_name+' profile'} style={{width:'100%',height:'100%',objectFit:'cover'}}/>:null}</div><div className="shiftmain"><b>{employer.company_name}</b><small className="shift-business">Company: {employer.company_name}</small><small className="shift-business">Location: {employer.company_location||'Location not provided'}</small><small className="shift-business">Roles available or previously listed: {employer.rolesAvailable?.length?employer.rolesAvailable.join(', '):'No roles listed yet'}</small>{employer.latest_shift&&<small className="shift-business">Most recent listed shift: {new Date(employer.latest_shift).toLocaleDateString('en-GB')}</small>}</div><div className="shiftpay"><button type="button" className={employer.isFavourite?'secondary':'primary'} disabled={busy} onClick={()=>toggleFavourite(employer)}>{employer.isFavourite?'✓ Added':'☆ Add to favourites'}</button></div></article>)}</div>}
 </section>;
}

function WorkerAvailability({action,busy,setNotice,setError,navigateTo}) {
 const [tab,setTab]=useState('confirmed');
 const [dates,setDates]=useState([]);
 const [timings,setTimings]=useState({});
 const [minHourlyRate,setMinHourlyRate]=useState('8');
 const [minWeeklyHours,setMinWeeklyHours]=useState('20');
 const [maxWeeklyHours,setMaxWeeklyHours]=useState('40');
 const [minTotalPay,setMinTotalPay]=useState('20');
 const [maxDistance,setMaxDistance]=useState('10');
 const [roles,setRoles]=useState([]);
 const [shiftTypes,setShiftTypes]=useState([]);
 const [automatic,setAutomatic]=useState(false);
 const [confirmAuto,setConfirmAuto]=useState(false);
 const [automaticConfirmed,setAutomaticConfirmed]=useState(false);
 const [loaded,setLoaded]=useState(false);
 const [startTime,setStartTime]=useState('09:00');
 const [endTime,setEndTime]=useState('17:00');
 const [rolesOpen,setRolesOpen]=useState(false);
 const [roleSearch,setRoleSearch]=useState('');
 const [typesOpen,setTypesOpen]=useState(false);
 const [employerMode,setEmployerMode]=useState('all');
 const [favouriteEmployers,setFavouriteEmployers]=useState([]);
 const [preferredEmployerIds,setPreferredEmployerIds]=useState([]);
 const [employersOpen,setEmployersOpen]=useState(false);
 const shiftTypeOptions=[['hospitality','Hospitality'],['bar','Bar work'],['warehouse','Warehouse'],['office','Office'],['retail','Retail'],['event','Events & festivals'],['clean','Cleaning'],['driving','Driving'],['other','Other']];
 useEffect(()=>{function closeDropdowns(event){if(!event.target.closest('.availability-collapsible.role-multi-filter'))setRolesOpen(false);if(!event.target.closest('.availability-collapsible.shift-type-multi-filter'))setTypesOpen(false);if(!event.target.closest('.availability-employer-preferences'))setEmployersOpen(false);}function closeOnEscape(event){if(event.key==='Escape'){setRolesOpen(false);setTypesOpen(false);setEmployersOpen(false);}}document.addEventListener('pointerdown',closeDropdowns);document.addEventListener('keydown',closeOnEscape);return()=>{document.removeEventListener('pointerdown',closeDropdowns);document.removeEventListener('keydown',closeOnEscape);};},[]);

 useEffect(()=>{Promise.all([request('/worker/availability'),request('/worker/employers/favourites')]).then(([r,f])=>{const d=r.availability||{};setTimings(d.timings||{});setMinHourlyRate(String(d.minHourlyRate??8));setMinWeeklyHours(String(d.minWeeklyHours??20));setMaxWeeklyHours(String(d.maxWeeklyHours??40));setMinTotalPay(String(d.minTotalPay??20));setMaxDistance(String(d.maxDistance??10));setRoles(d.roles||[]);setShiftTypes(d.shiftTypes||[]);setAutomatic(Boolean(d.automatic));setEmployerMode(d.employerMode||'all');setPreferredEmployerIds((d.preferredEmployerIds||[]).map(String));setFavouriteEmployers(f.employers||[]);setLoaded(true);}).catch(e=>{setError(e.message);setLoaded(true);});},[]);
 const calendar=Array.from({length:42},(_,i)=>{const d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()+i);const key=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');return {d,key};});
 const savePayload={timings,minWeeklyHours:Number(minWeeklyHours),maxWeeklyHours:Number(maxWeeklyHours),minHourlyRate:Number(minHourlyRate),minTotalPay:Number(minTotalPay),maxDistance:Number(maxDistance),roles,shiftTypes,automatic,employerMode,preferredEmployerIds:preferredEmployerIds.map(Number).filter(Number.isFinite)};
 async function save(payload,success){if(payload.timings)setTimings(payload.timings);await action(async()=>{const result=await request('/worker/availability',{method:'PUT',body:JSON.stringify(payload)});const d=result.availability||payload;setTimings(d.timings||payload.timings||{});setAutomatic(Boolean(d.automatic));setNotice(success);});}
 // Preference controls save automatically; no separate Save button is needed.
 useEffect(()=>{if(!loaded)return;const timer=setTimeout(()=>{request('/worker/availability',{method:'PUT',body:JSON.stringify(savePayload)}).catch(e=>setError(e.message));},500);return()=>clearTimeout(timer);},[loaded,minWeeklyHours,maxWeeklyHours,minHourlyRate,minTotalPay,maxDistance,roles,shiftTypes,automatic,employerMode,preferredEmployerIds]);
 async function addTimings(){if(!dates.length){setError('Select at least one date on the calendar first.');return;}const untilEnd=endTime==='shift_end';const nextDay=endTime.startsWith('nextday:');const endClock=nextDay?endTime.slice(8):endTime;if(startTime!=='anytime'&&(!startTime||(!untilEnd&&!nextDay&&(!endClock||endClock==='anytime'||startTime>=endClock)))){setError('Choose a valid end time. For shifts ending after midnight, choose a Next day time.');return;}const next={...timings};dates.forEach(date=>next[date]={start:startTime==='anytime'?'anytime':startTime,end:untilEnd?'shift_end':endTime,confirmed:false,anytime:startTime==='anytime'});setTimings(next);setDates([]);setNotice('Availability selected. Confirm automatic matching to publish these dates.');}
 async function removeDate(date){const next={...timings};delete next[date];await save({...savePayload,timings:next},'Confirmed availability removed.');setDates(cur=>cur.filter(d=>d!==date));}
 function editDate(date,timing){setTab('automation');setDates([date]);setStartTime(timing.start);setEndTime(timing.end);}
 function moveEmployer(id,direction){setPreferredEmployerIds(current=>{const next=[...current];const index=next.indexOf(String(id));const target=index+direction;if(index<0||target<0||target>=next.length)return current;[next[index],next[target]]=[next[target],next[index]];return next;});}
 const confirmedDates=Object.entries(timings).filter(([,t])=>t&&t.start&&t.end&&t.confirmed!==false).sort(([a],[b])=>a.localeCompare(b));
 const stagedDates=Object.entries(timings).filter(([,t])=>t&&t.start&&t.end&&t.confirmed===false).sort(([a],[b])=>a.localeCompare(b));
 const visibleRoles=JOB_ROLE_GROUPS.map(([group,items])=>[group,items.filter(name=>name.toLowerCase().includes(roleSearch.trim().toLowerCase()))]).filter(([,items])=>items.length);
 const selectedEmployers=preferredEmployerIds.map(String).map(id=>favouriteEmployers.find(e=>String(e.business_id)===id)).filter(Boolean);
 return <section className="panel worker-availability-panel"><h2>Availability</h2><p>Confirm the dates and times you can work over the next six weeks.</p><div className="job-tabs availability-subsection-tabs">{[['confirmed','Confirmed availability'],['automation','Availability automation']].map(([id,label])=><button type="button" key={id} className={tab===id?'active':''} onClick={()=>setTab(id)}>{label}</button>)}</div>
 {tab==='confirmed'?<div className="confirmed-availability-list confirmed-availability-only"><h3>Confirmed availability</h3>{confirmedDates.length===0?<div className="empty-state">You haven't confirmed any dates or times yet.</div>:confirmedDates.map(([date,t])=><article key={date} className="availability-date-row"><div><strong>{new Date(date+'T12:00:00').toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'short',year:'numeric'})}</strong><span>{t.anytime||t.start==='anytime'?'Anytime'+(t.end==='shift_end'?' – until shift ends':t.end&&t.end.startsWith('nextday:')?' – until '+t.end.slice(8)+' next day':t.end&&t.end!=='anytime'?' – until '+t.end:''):t.start+' – '+(t.end==='shift_end'?'until shift ends':t.end&&t.end.startsWith('nextday:')?'until '+t.end.slice(8)+' next day':t.end)}</span></div><button type="button" className="secondary" disabled={busy} onClick={()=>removeDate(date)}>Remove</button></article>)}</div>
 :<div className="availability-automation-settings">
 <h3>Shift preferences</h3><p>Choose the roles, shift types and employers you want hyrz to consider.</p><div className="availability-hours-request"><h3>Requested weekly hours</h3><p>These preferences are used only when automated matching is enabled. Your accepted shifts across all Hyrz employers count towards your maximum, so employers can see how many hours you still have available.</p><div className="availability-hours-fields"><label>Minimum hours per week<input type="number" min="0" max="80" step="1" value={minWeeklyHours} onChange={e=>setMinWeeklyHours(e.target.value)}/></label><label>Maximum hours per week<input type="number" min="1" max="80" step="1" value={maxWeeklyHours} onChange={e=>setMaxWeeklyHours(e.target.value)}/></label></div><small>Choose between 0 and 80 hours. Your maximum cannot be lower than your minimum.</small></div>
 <div className="availability-collapsible shift-type-multi-filter"><label className="shift-type-filter-label">Shift types</label><button type="button" className="shift-type-picker-toggle" aria-expanded={typesOpen} onClick={()=>setTypesOpen(v=>!v)}>{shiftTypes.length===0?'All types':shiftTypes.length+' selected'} <span>{typesOpen?'▴':'▾'}</span></button>{shiftTypes.length>0&&<button type="button" className="role-clear-button shift-type-clear-button" onClick={()=>setShiftTypes([])}>Clear selected shift types</button>}{typesOpen&&<div className="shift-type-picker-panel"><div className="shift-type-picker-options">{shiftTypeOptions.map(([value,label])=><label key={value} className="shift-type-picker-option"><input type="checkbox" checked={shiftTypes.includes(value)} onChange={e=>setShiftTypes(cur=>e.target.checked?[...cur,value]:cur.filter(x=>x!==value))}/><span>{label}</span></label>)}</div><div className="shift-type-picker-footer"><button type="button" onClick={()=>setShiftTypes([])}>Clear</button><button type="button" onClick={()=>setTypesOpen(false)}>Done</button></div></div>}</div>
 <div className="availability-collapsible role-multi-filter"><div className="role-multi-filter-heading"><span>Roles</span><button type="button" className="role-picker-toggle" aria-expanded={rolesOpen} onClick={()=>setRolesOpen(v=>!v)}>{roles.length===0?'All roles':roles.length+' selected'} <span>{rolesOpen?'▴':'▾'}</span></button></div><small className="role-filter-hint">No selection includes every role.</small>{roles.length>0&&<button type="button" className="role-clear-button" onClick={()=>setRoles([])}>Clear selected roles</button>}{rolesOpen&&<div className="role-picker-panel"><input type="search" aria-label="Search preferred job roles" placeholder="Search job roles…" value={roleSearch} onChange={e=>setRoleSearch(e.target.value)}/><div className="role-picker-options">{visibleRoles.map(([group,items])=><fieldset key={group} className="role-picker-group"><legend>{group}</legend>{items.map(name=><label key={name} className="role-picker-option"><input type="checkbox" checked={roles.includes(name)} onChange={e=>setRoles(cur=>e.target.checked?[...cur,name]:cur.filter(x=>x!==name))}/><span>{name}</span></label>)}</fieldset>)}</div><div className="role-picker-footer"><span>{roles.length} selected</span><button type="button" onClick={()=>setRolesOpen(false)}>Done</button></div></div>}</div>
 <div className="availability-employer-preferences"><h4>Employers</h4><label className="availability-employer-mode">Employers to consider<select value={employerMode} onChange={e=>setEmployerMode(e.target.value)}><option value="all">All employers</option><option value="favourites">All my favourites</option><option value="selected">Choose specific favourites</option></select></label>{employerMode==='favourites'&&<p className="muted">Automated matching can consider shifts from every employer in your My favourites list.</p>}{employerMode==='selected'&&<><p className="muted">Select the favourite employers you want to receive shift matches from. You can select more than one.</p>{favouriteEmployers.length===0?<p className="muted">You haven't added any employers to My favourites yet. Add employers to your favourites first.</p>:<div className="availability-favourite-employer-list">{favouriteEmployers.map(employer=><label key={employer.business_id} className="availability-favourite-employer-option"><input type="checkbox" checked={preferredEmployerIds.includes(String(employer.business_id))} onChange={e=>setPreferredEmployerIds(cur=>e.target.checked?[...cur,String(employer.business_id)]:cur.filter(id=>id!==String(employer.business_id)))}/><span><strong>{employer.company_name}</strong>{employer.company_location&&<small>{employer.company_location}</small>}</span></label>)}</div>}{selectedEmployers.length>0&&<div className="availability-employer-priority"><strong>Employer priority</strong><small>First listed has highest priority if suitable shifts clash.</small>{selectedEmployers.map((employer,index)=><div className="availability-employer-priority-row" key={employer.business_id}><span>{index+1}. {employer.company_name}</span><div><button type="button" className="secondary" aria-label={'Move '+employer.company_name+' up'} disabled={index===0} onClick={()=>moveEmployer(employer.business_id,-1)}>↑</button><button type="button" className="secondary" aria-label={'Move '+employer.company_name+' down'} disabled={index===selectedEmployers.length-1} onClick={()=>moveEmployer(employer.business_id,1)}>↓</button></div></div>)}</div>}</>}</div>
 <div className="availability-rate-settings"><div className="grid2"><label>Minimum hourly rate (£)<input type="number" min="8" step="0.50" value={minHourlyRate} onChange={e=>setMinHourlyRate(String(Math.max(8,Number(e.target.value)||8)))}/></label><label>Minimum total shift pay (£)<input type="number" min="8" step="1" value={minTotalPay} onChange={e=>setMinTotalPay(String(Math.max(8,Number(e.target.value)||8)))}/></label><label>Maximum travel distance (miles)<input type="number" min="1" step="1" value={maxDistance} onChange={e=>setMaxDistance(String(Math.max(1,Math.floor(Number(e.target.value)||1))))}/></label></div></div>
 <div className="availability-timing-editor availability-timing-editor-inline"><h3>Choose dates and timings</h3><p>Select one or more dates, choose your working hours, and add them to confirmed availability.</p><div className="rolling-shift-calendar"><div className="rolling-calendar-heading"><strong>Next 6 weeks</strong><span className="muted">{dates.length?dates.length+' date(s) selected':'Select one or more dates'}</span></div><div className="rolling-calendar-days">{calendar.map(({d,key})=><button type="button" key={key} aria-pressed={dates.includes(key)} className={'rolling-calendar-day'+(dates.includes(key)?' selected':'')} onClick={()=>{if(dates.includes(key)){setDates(cur=>cur.filter(x=>x!==key));}else{setDates(cur=>[...cur,key]);setStartTime('09:00');setEndTime('17:00');}}}><small>{d.toLocaleDateString('en-GB',{weekday:'short'})}</small><strong>{d.getDate()}</strong><span>{d.toLocaleDateString('en-GB',{month:'short'})}</span></button>)}</div></div><div className="grid2"><label>Available from<select value={startTime} onChange={e=>{const next=e.target.value;setStartTime(next);if(next!=='anytime'){const minimum=Number(next.slice(0,2))*60+Number(next.slice(3,5))+60;const minimumValue=String(Math.floor(minimum/60)%24).padStart(2,'0')+':'+String(minimum%60).padStart(2,'0');if(endTime==='shift_end'||endTime==='anytime'||endTime.startsWith('nextday:')||endTime<minimumValue)setEndTime(minimum<1440?minimumValue:'nextday:'+minimumValue);}}}><option value="anytime">Anytime</option>{Array.from({length:96},(_,i)=>{const minutes=i*15,h=String(Math.floor(minutes/60)).padStart(2,'0'),m=String(minutes%60).padStart(2,'0'),value=h+':'+m;return <option key={value} value={value}>{value}</option>})}</select></label><label>Available until<select value={endTime} onChange={e=>setEndTime(e.target.value)}><option value="shift_end">Until shift ends</option>{Array.from({length:96},(_,i)=>{const minutes=i*15,h=String(Math.floor(minutes/60)).padStart(2,'0'),m=String(minutes%60).padStart(2,'0'),value=h+':'+m,startMinutes=startTime==='anytime'?-60:Number(startTime.slice(0,2))*60+Number(startTime.slice(3,5));return {value,minutes,valid:startTime==='anytime'||minutes>=startMinutes+60};}).filter(item=>item.valid).map(({value})=><option key={value} value={value}>{value}</option>) }<optgroup label="Next day (after midnight)">{Array.from({length:96},(_,i)=>{const minutes=i*15,h=String(Math.floor(minutes/60)).padStart(2,'0'),m=String(minutes%60).padStart(2,'0'),value=h+':'+m,nextValue='nextday:'+value;return <option key={nextValue} value={nextValue}>{value} (next day)</option>})}</optgroup></select></label></div><button type="button" className="primary" disabled={!dates.length||busy} onClick={addTimings}>Add dates for confirmation</button><p className="availability-confirmed-feedback">{dates.length?'Selected dates will appear below when confirmed.':''}</p><div className="confirmed-availability-list"><h3>Confirmed availabilities</h3>{confirmedDates.length===0&&stagedDates.length===0?<p className="muted">No dates added yet.</p>:<>{stagedDates.map(([date,t])=><article key={date} className="availability-date-row"><div><strong>{new Date(date+'T12:00:00').toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'short',year:'numeric'})}</strong><span>{t.start==='anytime'?'Any time':t.start} – {t.end==='shift_end'?'Until the shift ends':t.end&&t.end.startsWith('nextday:')?'Until '+t.end.slice(8)+' the following day':t.end}</span><small>Awaiting automatic matching confirmation</small></div><button type="button" className="secondary" onClick={()=>editDate(date,t)}>Edit</button><button type="button" className="secondary" onClick={()=>{setTimings(current=>{const next={...current};delete next[date];return next;});}}>Remove</button></article>)}{confirmedDates.map(([date,t])=><article key={date} className="availability-date-row"><div><strong>{new Date(date+'T12:00:00').toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'short',year:'numeric'})}</strong><span>{t.start==='anytime'?'Any time':t.start} – {t.end==='shift_end'?'Until the shift ends':t.end&&t.end.startsWith('nextday:')?'Until '+t.end.slice(8)+' the following day':t.end}</span></div><button type="button" className="secondary" onClick={()=>editDate(date,t)}>Edit</button><button type="button" className="secondary" disabled={busy} onClick={()=>removeDate(date)}>Remove</button></article>)}</>}</div></div>
 {!confirmAuto&&!automaticConfirmed&&<button type="button" className="primary availability-enable-button" onClick={()=>setConfirmAuto(true)}>Confirm automatic matching</button>}
 {confirmAuto&&<div className="availability-confirm-dialog" role="dialog" aria-modal="true"><h3>Confirm automatic matching</h3><p>Confirm to activate automatic matching and publish the availability dates you have selected. Only confirmed dates will appear under Confirmed availability.</p><div><button type="button" className="primary" disabled={busy} onClick={async()=>{if(busy)return;const confirmedTimings=Object.fromEntries(Object.entries(timings).map(([date,t])=>[date,{...t,confirmed:true}]));await save({...savePayload,automatic:true,timings:confirmedTimings},'Automatic matching confirmed and availability published.');setAutomaticConfirmed(true);setConfirmAuto(false);requestAnimationFrame(()=>{const main=document.querySelector('.app.worker main');if(main)main.scrollTo({top:0,behavior:'smooth'});window.scrollTo({top:0,behavior:'smooth'});document.documentElement.scrollTop=0;document.body.scrollTop=0;});}}>Confirm automatic matching</button><button type="button" className="secondary" onClick={()=>setConfirmAuto(false)}>Cancel</button></div></div>}
 </div>}
 </section>;
}

function BroadcastNotifications({setError,setNotice}) {
 const [items,setItems]=useState([]);const [loaded,setLoaded]=useState(false);
 const load=()=>request('/notifications/mine').then(r=>setItems(r.notifications||[])).catch(e=>setError(e.message)).finally(()=>setLoaded(true));
 useEffect(()=>{load();},[]);
 async function markRead(n){try{await request('/notifications/'+n.id+'/read',{method:'PATCH',body:'{}'});setItems(old=>old.map(x=>x.id===n.id?{...x,read_at:new Date().toISOString()}:x));setNotice('Notification marked as read.');}catch(e){setError(e.message);}}
 return <section className="panel"><span className="eyebrow">hyrz UPDATES</span><h2>Notifications</h2><p>Important updates and announcements from hyrz.</p>{!loaded?<div className="empty-state">Loading notifications…</div>:items.length?items.map(n=><article className={'worker-notification-item '+(!n.read_at?'admin-broadcast-unread':'')} key={n.id}><div className="worker-notification-item-heading"><strong>{n.title}</strong><small>{new Date(n.created_at).toLocaleString('en-GB')}</small></div><p>{n.body}</p>{!n.read_at&&<button className="secondary" onClick={()=>markRead(n)}>Mark as read</button>}</article>):<div className="empty-state">You have no hyrz notifications at the moment.</div>}</section>;
}

function WorkerNotifications({navigateTo,setError,setNotice,adminBroadcasts,setAdminBroadcasts}) {
 const [tab,setTab]=useState('all');
 const [preferences,setPreferences]=useState({shiftReminders:{email:true,inApp:true},shiftAcceptances:{email:true,inApp:true},shiftRescindments:{email:true,inApp:true},hyrzUpdates:{email:true,inApp:true}});
 const [applications,setApplications]=useState([]);
 const [messages,setMessages]=useState([]);
 const [loaded,setLoaded]=useState(false);
 const [saving,setSaving]=useState(false);
 useEffect(()=>{let active=true;const load=async()=>{const endpoints=['/worker/notification-preferences','/applications/mine','/messages/mine','/notifications/mine'];const results=await Promise.allSettled(endpoints.map(path=>request(path)));if(!active)return;const [p,a,m,n]=results.map(result=>result.status==='fulfilled'&&result.value&&typeof result.value==='object'?result.value:{});const failures=results.filter(result=>result.status==='rejected');if(p.preferences&&typeof p.preferences==='object')setPreferences(current=>({...current,...p.preferences}));setApplications(Array.isArray(a.applications)?a.applications:[]);setMessages(Array.isArray(m.messages)?m.messages:[]);setAdminBroadcasts(Array.isArray(n.notifications)?n.notifications:[]);if(failures.length)setError('Some notification information could not be loaded. Please refresh and try again.');setLoaded(true)};load().catch(e=>{if(active){setError(e?.message||'Could not load notifications.');setLoaded(true)}});return()=>{active=false}},[]);
 const updatePreference=async(type,channel,value)=>{const next={...preferences,[type]:{...preferences[type],[channel]:value}};setPreferences(next);setSaving(true);try{await request('/worker/notification-preferences',{method:'PUT',body:JSON.stringify({preferences:next})});setNotice('Notification settings saved.');}catch(e){setError(e.message);}finally{setSaving(false);}};
 const types=[['shiftReminders','Shift reminders','Reminders about upcoming shifts.'],['shiftAcceptances','Shift acceptances','When an employer accepts your application.'],['shiftRescindments','Shift rescindments','When an accepted shift is rescinded or withdrawn.'],['hyrzUpdates','hyrz notifications','Important updates and messages from the hyrz team.']];
 const rows=applications.map(app=>{const status=String(app.status||'').toLowerCase();if(status==='approved')return {id:'accepted-'+app.id,type:'acceptances',title:'Shift accepted',body:app.title||'Your shift application was accepted.',date:app.updated_at||app.created_at,shift:app};if(['rescinded','cancelled','withdrawn'].includes(status))return {id:'rescinded-'+app.id,type:'rescinded',title:'Shift rescinded',body:(app.title||'Your shift')+' is no longer confirmed.',date:app.updated_at||app.created_at,shift:app};return null}).filter(Boolean);
 const hyrzRows=(Array.isArray(messages)?messages:[]).filter(m=>m&&(m.sender_role==='admin'||m.recipient_role==='admin')).map(m=>({id:'hyrz-'+m.id,type:'hyrz',title:m.subject||'Message from hyrz',body:m.body||'You have an update from hyrz.',date:m.created_at,message:m}));
 const broadcastRows=(Array.isArray(adminBroadcasts)?adminBroadcasts:[]).filter(Boolean).map(n=>({id:'broadcast-'+n.id,type:'hyrz',title:n.title,body:n.body,date:n.created_at,broadcast:n}));
 const allRows=[...rows,...hyrzRows,...broadcastRows].sort((x,y)=>new Date(y.date||0)-new Date(x.date||0));
 const shown=tab==='all'?allRows:tab==='acceptances'?allRows.filter(n=>n.type==='acceptances'):tab==='rescinded'?allRows.filter(n=>n.type==='rescinded'):tab==='hyrz'?allRows.filter(n=>n.type==='hyrz'):tab==='unread'?[...hyrzRows.filter(n=>!n.message?.read_at),...broadcastRows.filter(n=>!n.broadcast?.read_at)]:[];
 return <section className="panel worker-notifications-panel"><header className="notification-page-heading"><span className="eyebrow">STAY IN THE LOOP</span><h2>Notifications</h2><p>See shift acceptances, shift rescindments and updates from hyrz.</p></header><div className="job-tabs notification-tabs">{[['all','All'],['acceptances','Shift acceptances'],['rescinded','Shift rescindments'],['hyrz','hyrz notifications'],['unread','Unread'],['settings','Settings']].map(([id,label])=><button type="button" key={id} className={tab===id?'active':''} onClick={()=>setTab(id)}>{label}</button>)}</div>{tab==='settings'?<div className="notification-settings"><div className="notification-settings-intro"><h3>Notification preferences</h3><p>Choose how you receive each type of update. Email and in-app notifications can be switched on or off separately.</p></div><div className="notification-settings-list">{types.map(([type,label,description])=><article className="notification-setting-row" key={type}><div className="notification-setting-copy"><strong>{label}</strong><p>{description}</p></div><div className="notification-channel-toggles">{[['email','Email'],['inApp','In-app']].map(([channel,title])=><label className="notification-toggle-option" key={channel}><span>{title}</span><input className="notification-switch" type="checkbox" role="switch" aria-label={title+' notifications for '+label} checked={Boolean(preferences[type]?.[channel])} disabled={!loaded||saving} onChange={e=>updatePreference(type,channel,e.target.checked)}/></label>)}</div></article>)}</div>{saving&&<p className="muted notification-saving">Saving settings…</p>}</div>:<div className="worker-notification-list" aria-live="polite">{!loaded?<div className="empty-state">Loading notifications…</div>:shown.length?shown.map(n=><article className="worker-notification-item" key={n.id}><div className="worker-notification-item-heading"><strong>{n.title}</strong><small>{n.date?new Date(n.date).toLocaleString('en-GB'):'Recent'}</small></div><p>{n.body}</p>{n.type==='hyrz'&&n.broadcast&&!n.broadcast.read_at&&<button type="button" className="secondary" onClick={async()=>{try{await request('/notifications/'+n.broadcast.id+'/read',{method:'PATCH',body:'{}'});setAdminBroadcasts(old=>old.map(x=>x.id===n.broadcast.id?{...x,read_at:new Date().toISOString()}:x));setNotice('Notification marked as read.');}catch(e){setError(e.message);}}}>Mark as read</button>}</article>):<div className="empty-state">{tab==='acceptances'?'No shift acceptances to show yet.':tab==='rescinded'?'No shift rescindments to show yet.':tab==='hyrz'?'No hyrz notifications to show yet.':tab==='unread'?'You have no unread hyrz notifications.':'No notifications yet. Shift and hyrz updates will appear here when available.'}</div>}</div>}</section>;
}

function WorkerInbox({user,action,busy,setNotice,setError,goBack,inboxTab='all',setInboxTab=()=>{},inboxSearch='',workchatItems=[],onOpenWorkchat=()=>{}}) {
 const [composeOpen,setComposeOpen]=useState(false),[messages,setMessages]=useState([]),[loading,setLoading]=useState(true),[filter,setFilter]=useState('all'),[activeInboxMessage,setActiveInboxMessage]=useState(null),[inboxReplyDraft,setInboxReplyDraft]=useState(''),[directSearch,setDirectSearch]=useState('');
 const [directConversations,setDirectConversations]=useState([]),[activeDirectConversation,setActiveDirectConversation]=useState(null),[directMessages,setDirectMessages]=useState([]),[directDraft,setDirectDraft]=useState('');
 async function refreshMessages(){try{const r=await request('/messages/mine');setMessages(r.messages||[]);}catch(e){setError(e.message)}finally{setLoading(false)}}
 async function refreshDirect(){try{const r=await request('/conversations/mine');setDirectConversations(r.conversations||[])}catch(e){setError(e.message)}}
 useEffect(()=>{refreshMessages();refreshDirect()},[]);
 useEffect(()=>{if(!activeDirectConversation)return;let active=true;const load=async()=>{try{const r=await request('/conversations/'+activeDirectConversation+'/messages');if(active){setDirectMessages(r.messages||[]);await refreshDirect()}}catch(e){if(active)setError(e.message)}};load();const timer=setInterval(load,5000);return()=>{active=false;clearInterval(timer)}},[activeDirectConversation]);
 async function sendDirect(e){e.preventDefault();if(!directDraft.trim()||!activeDirectConversation)return;const body=directDraft.trim();await action(async()=>{await request('/conversations/'+activeDirectConversation+'/messages',{method:'POST',body:JSON.stringify({body})});setDirectDraft('');const r=await request('/conversations/'+activeDirectConversation+'/messages');setDirectMessages(r.messages||[]);await refreshDirect()})}
 const inSection=m=>{const isAdmin=(m.sender_role==='worker'&&m.recipient_role==='admin')||(m.sender_role==='admin'&&m.recipient_role==='worker');const isEmployer=(m.sender_role==='worker'&&m.recipient_role==='employer')||(m.sender_role==='employer'&&m.recipient_role==='worker');return inboxTab==='all'?isAdmin||isEmployer:inboxTab==='admins'?isAdmin:inboxTab==='employers'?isEmployer:false;};
 const sectionMessages=messages.filter(inSection),visible=sectionMessages.filter(m=>filter==='all'?true:filter==='received'?Number(m.sender_id)!==Number(user.id):filter==='sent'?Number(m.sender_id)===Number(user.id):Number(m.sender_id)!==Number(user.id)&&!m.read_at);
 const unreadCount=sectionMessages.filter(m=>Number(m.sender_id)!==Number(user.id)&&!m.read_at).length;
 const employerUnreadCount=directConversations.reduce((total,conversation)=>total+Number(conversation.unread_count||0),0);
 const directVisible=directConversations.filter(conversation=>{
   const searchText=[conversation.participant_first_name,conversation.participant_last_name].filter(Boolean).join(' ').toLowerCase();if((directSearch.trim()||inboxSearch.trim())&&!searchText.includes((inboxSearch.trim()||directSearch.trim()).toLowerCase()))return false;
   if(filter==='all')return true;
   if(filter==='unread')return Number(conversation.unread_count||0)>0;
   const lastSenderId=conversation.last_message_sender_id??conversation.last_sender_id??conversation.last_message_from_id;
   if(lastSenderId===undefined||lastSenderId===null)return false;
   return filter==='received'?Number(lastSenderId)!==Number(user.id):Number(lastSenderId)===Number(user.id);
 });
 async function openInboxMessage(message){
   setActiveInboxMessage(message);setInboxReplyDraft('');
   if(Number(message.sender_id)===Number(user.id)||message.read_at)return;
   setMessages(current=>current.map(item=>item.id===message.id?{...item,read_at:new Date().toISOString()}:item));
   try{await request('/messages/'+message.id+'/read',{method:'POST',body:JSON.stringify({})});await refreshMessages();}
   catch(error){setError(error.message||'Could not mark message as read.');await refreshMessages();}
 }
 return <section className="panel worker-inbox-panel">
  <div className="worker-inbox-heading"><div><h2>Inbox</h2><p>Your conversations and messages.</p></div></div>
  
  
  {(inboxTab==='employers'||inboxTab==='all')?<div className="worker-direct-inbox">{inboxTab==='employers'&&(activeDirectConversation?<><div className="direct-thread-heading"><div><h4>{(()=>{const c=directConversations.find(x=>Number(x.id)===Number(activeDirectConversation));return c?[c.participant_first_name,c.participant_last_name].filter(Boolean).join(' ')||'Employer': 'Employer'})()}</h4><small>{directConversations.find(x=>Number(x.id)===Number(activeDirectConversation))?.participant_email||''}</small><small className="direct-presence-label">{messagingPresenceLabel(directConversations.find(x=>Number(x.id)===Number(activeDirectConversation))?.participant_last_seen_at)}</small></div><button type="button" className="secondary icon-back-button" aria-label="Back to conversations" title="Back to conversations" onClick={()=>setActiveDirectConversation(null)}><svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M9 14 4 9l5-5"/><path d="M4 9h9a7 7 0 0 1 7 7v4"/></svg></button></div><div className="direct-message-history">{directMessages.map(m=><article key={m.id} className={'direct-message-bubble'+(Number(m.sender_id)===Number(user.id)?' sent':' received')}><p>{m.body}</p><small>{Number(m.sender_id)===Number(user.id)?'You':([m.sender_first_name,m.sender_last_name].filter(Boolean).join(' ')||'Employer')} · {new Date(m.created_at).toLocaleString('en-GB')}{Number(m.sender_id)===Number(user.id)&&<span className={'direct-read-ticks'+(m.read_at?' is-read':'')} aria-label={m.read_at?'Read':'Sent'}> ✓✓</span>}</small></article>)}</div><form className="direct-message-compose" onSubmit={sendDirect}><textarea value={directDraft} onKeyDown={handleMessageEnter} onChange={e=>setDirectDraft(e.target.value)} placeholder="Reply to your employer…" maxLength={5000} required/><button className="primary" disabled={busy||!directDraft.trim()}>Send message</button></form></>:directVisible.length===0?<div className="empty-state">{directConversations.length===0?'Your employer conversations will appear here when an employer messages you.':filter==='unread'?'You have no unread employer conversations.':filter==='received'?'No conversations with a latest reply from an employer.':filter==='sent'?'No conversations with a latest reply from you.':'No employer conversations to show.'}</div>:<><div className="direct-conversation-list worker-direct-conversation-list">{directVisible.map(c=><button type="button" key={c.id} className="workchat-wa-row" onClick={()=>setActiveDirectConversation(Number(c.id))}><span className="workchat-wa-avatar">{c.participant_profile_picture?<img src={c.participant_profile_picture} alt=""/>:<b>{(c.participant_first_name||'E').charAt(0).toUpperCase()}</b>}</span><span className="workchat-wa-copy"><strong>{[c.participant_first_name,c.participant_last_name].filter(Boolean).join(' ')||'Employer'}</strong><small>{c.last_message||'No messages yet'}{Number(c.last_message_sender_id)===Number(user.id)&&<span className={'direct-read-ticks'+(c.last_message_read_at?' is-read':'')} aria-label={c.last_message_read_at?'Read':'Sent'}> ✓✓</span>}</small></span><span className="workchat-wa-meta"><time>{c.last_message_created_at?new Date(c.last_message_created_at).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'}):''}</time>{Number(c.unread_count)>0&&<b className="direct-unread-count">{c.unread_count}</b>}</span></button>)}</div></>)}{inboxTab==='all'&&<div className="inbox-all-conversations">{[
...directVisible.filter(c=>!inboxSearch.trim()||[c.participant_first_name,c.participant_last_name,c.last_message].filter(Boolean).join(' ').toLowerCase().includes(inboxSearch.trim().toLowerCase())).map(c=>({kind:'employer',id:c.id,date:c.last_message_created_at||c.created_at||0,data:c})),
...workchatItems.filter(c=>c.status==='current'&&(!inboxSearch.trim()||[c.name,c.last_message,c.company_name,c.business_name].filter(Boolean).join(' ').toLowerCase().includes(inboxSearch.trim().toLowerCase()))).map(c=>({kind:'workchat',id:c.id,date:c.last_message_at||c.created_at||0,data:c})),
...messages.filter(m=>((m.sender_role==='worker'&&m.recipient_role==='admin')||(m.sender_role==='admin'&&m.recipient_role==='worker'))&&(!inboxSearch.trim()||[m.subject,m.body,m.sender_name].filter(Boolean).join(' ').toLowerCase().includes(inboxSearch.trim().toLowerCase()))).map(m=>({kind:'admin',id:m.id,date:m.created_at||0,data:m}))
].sort((a,b)=>new Date(b.date).getTime()-new Date(a.date).getTime()).map(item=>{
const d=item.data;
const title=item.kind==='workchat'?(d.name||'Workchat'):item.kind==='employer'?([d.participant_first_name,d.participant_last_name].filter(Boolean).join(' ')||'Employer'):(d.subject||'Hyrz support');
const preview=d.last_message||d.latest_message||d.body||'No messages yet';
const avatar=item.kind==='workchat'?(d.profile_picture||''):item.kind==='employer'?(d.participant_profile_picture||''):null;
const unread=Number(d.unread_count||0)||(item.kind==='admin'&&!d.read_at&&Number(d.sender_id)!==Number(user.id)?1:0);
return <button type="button" key={item.kind+'-'+item.id} className="workchat-wa-row" onClick={()=>item.kind==='workchat'?onOpenWorkchat(d.id):item.kind==='employer'?setActiveDirectConversation(Number(d.id)):openInboxMessage(d)}>
<span className="workchat-wa-avatar">{avatar?<img src={avatar} alt=""/>:<b>{item.kind==='workchat'?workchatInitials(d.name):item.kind==='employer'?(d.participant_first_name||'E').charAt(0).toUpperCase():'H'}</b>}</span>
<span className="workchat-wa-copy"><strong>{title}</strong><small>{preview}</small></span>
<span className="workchat-wa-meta"><time>{d.last_message_at||d.last_message_created_at?new Date(d.last_message_at||d.last_message_created_at).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'}):d.created_at?new Date(d.created_at).toLocaleDateString('en-GB'):''}</time>{unread>0&&<b className="direct-unread-count">{unread>99?'99+':unread}</b>}</span>
</button>;
})}{directVisible.length===0&&workchatItems.filter(c=>c.status==='current').length===0&&messages.filter(m=>(m.sender_role==='worker'&&m.recipient_role==='admin')||(m.sender_role==='admin'&&m.recipient_role==='worker')).length===0&&<div className="empty-state">Your conversations will appear here.</div>}</div>}</div>:<>{activeInboxMessage?<div className="worker-inbox-thread"><div className="worker-inbox-thread-heading"><h3>{activeInboxMessage.subject||'Message'}</h3><small>{new Date(activeInboxMessage.created_at).toLocaleString('en-GB')}</small></div>{messages.filter(m=>{const base=activeInboxMessage;const otherId=Number(base.sender_id)===Number(user.id)?Number(base.recipient_id):Number(base.sender_id);const sameSubject=String(m.subject||'').replace(/^re:\\s*/i,'').trim().toLowerCase()===String(base.subject||'').replace(/^re:\\s*/i,'').trim().toLowerCase();return sameSubject&&[Number(m.sender_id),Number(m.recipient_id)].includes(otherId)&&[Number(m.sender_id),Number(m.recipient_id)].includes(Number(user.id))}).sort((a,b)=>new Date(a.created_at)-new Date(b.created_at)).map(m=><article key={m.id} className={'worker-inbox-thread-message'+(Number(m.sender_id)===Number(user.id)?' sent':' received')}><p>{m.body}</p><small>{Number(m.sender_id)===Number(user.id)?'You':m.sender_name||m.sender_email||'Support team'} · {new Date(m.created_at).toLocaleString('en-GB')}</small></article>)}<form className="worker-inbox-thread-reply" onSubmit={async e=>{e.preventDefault();if(!inboxReplyDraft.trim())return;const recipientId=Number(activeInboxMessage.sender_id)===Number(user.id)?Number(activeInboxMessage.recipient_id):Number(activeInboxMessage.sender_id);await action(async()=>{await request('/messages',{method:'POST',body:JSON.stringify({category:activeInboxMessage.category||'enquiries',subject:'Re: '+String(activeInboxMessage.subject||'Message').replace(/^Re:\\s*/i,''),body:inboxReplyDraft.trim(),recipientId})});setInboxReplyDraft('');await refreshMessages();setNotice('Reply sent.')})}}><label htmlFor="inbox-thread-reply">Your reply</label><textarea id="inbox-thread-reply" value={inboxReplyDraft} onKeyDown={handleMessageEnter} onChange={e=>setInboxReplyDraft(e.target.value)} maxLength={5000} required placeholder="Write your reply…"/><button type="submit" className="primary" disabled={busy||!inboxReplyDraft.trim()}>Send reply</button></form></div>:<>{composeOpen&&<div className="worker-inbox-compose"><div className="worker-inbox-compose-heading"><h3>New message</h3><p>Send a new message to hyrz support.</p></div><SupportContact user={user} action={action} busy={busy} setNotice={setNotice} setError={setError}/></div>}<div className="worker-inbox-messages">{loading?<p className="muted">Loading messages…</p>:visible.length===0?<div className="empty-state">No {filter==='all'?'messages':filter+' messages'} to show.</div>:visible.map(m=><button type="button" className="workchat-wa-row" key={m.id} onClick={()=>openInboxMessage(m)}><span className="workchat-wa-avatar"><b>H</b></span><span className="workchat-wa-copy"><strong>{m.subject||'Message'}</strong><small>{m.body||'No message preview'}</small></span><span className="workchat-wa-meta"><time>{new Date(m.created_at).toLocaleDateString('en-GB')}</time>{!m.read_at&&Number(m.sender_id)!==Number(user.id)&&<b className="direct-unread-count">1</b>}</span></button>)}</div></>}</>}
 </section>;
}

function SupportContact({user,action,busy,setNotice,setError}) {
 const [category,setCategory]=useState('enquiries');
 const [subject,setSubject]=useState('');
 const [body,setBody]=useState('');
 const [recipientId,setRecipientId]=useState('');
 const [messages,setMessages]=useState([]);
 const [sent,setSent]=useState(false);
 async function refreshMessages(){try{const r=await request('/messages/mine');setMessages(r.messages||[]);}catch(e){setError(e.message);}}
 useEffect(()=>{refreshMessages();},[]);
 async function submit(e){e.preventDefault();setSent(false);await action(async()=>{await request('/messages',{method:'POST',body:JSON.stringify({category,subject,body,...(recipientId?{recipientId:Number(recipientId)}:{})})});setBody('');setSubject('');setRecipientId('');setSent(true);setNotice('Your message has been sent to hyrz support.');await refreshMessages();});}
 function reply(m){setRecipientId(String(m.sender_id===user.id?m.recipient_id:m.sender_id));setCategory(m.category||'enquiries');setSubject('Re: '+(m.subject||'your message').replace(/^Re:\s*/i,''));window.scrollTo({top:document.body.scrollHeight,behavior:'smooth'});}
 return <section className="panel admin-message-form"><h2>Contact hyrz support</h2><p>Send a message for the support team to review.</p><form onSubmit={submit}><label>Message type<select value={category} onChange={e=>setCategory(e.target.value)}><option value="enquiries">Enquiry</option><option value="complaints">Complaint</option><option value="checkout_disputes">Checkout dispute</option><option value="appeal_strikes">Appeal strikes</option></select></label><label>Subject<input required minLength="2" maxLength="200" value={subject} onChange={e=>setSubject(e.target.value)}/></label><label>Message<textarea required maxLength="5000" value={body} onKeyDown={handleMessageEnter} onChange={e=>setBody(e.target.value)}/></label><button className="primary" disabled={busy}>Send to support</button>{sent&&<p role="status">Message sent successfully.</p>}</form></section>;
}

function PasswordField(props){
 const [visible,setVisible]=useState(false);
 return <span className="password-field">
  <input {...props} type={visible?'text':'password'}/>
  <button type="button" className="password-visibility-toggle" aria-label={visible?'Hide password':'Show password'} aria-pressed={visible} title={visible?'Hide password':'Show password'} onClick={()=>setVisible(value=>!value)}>
   {visible?<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M3 3l18 18M10.6 10.6a2 2 0 0 0 2.8 2.8"/><path d="M9.9 5.2A11.8 11.8 0 0 1 12 5c5.2 0 9 4.5 10 7-.4 1-1.4 2.5-3 3.8M6.2 6.2C3.8 7.7 2.4 10 2 12c1 2.5 4.8 7 10 7 1 0 2-.2 2.9-.5"/></svg>:<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/></svg>}
  </button>
 </span>;
}

function checkoutDateTimeLocal(value){
 if(!value)return '';
 const date=new Date(value);
 if(Number.isNaN(date.getTime()))return String(value).replace(' ','T').slice(0,16);
 const local=new Date(date.getTime()-date.getTimezoneOffset()*60000);
 return local.toISOString().slice(0,16);
}
function ShiftConfirmationRequests({setNotice,setError,onRefresh}) {
 const [items,setItems]=useState([]);
 const [loaded,setLoaded]=useState(false);
 const [accepted,setAccepted]=useState({});
 const [busyId,setBusyId]=useState(null);
 async function load(){try{const result=await request('/shift-confirmations/mine');setItems(result.confirmations||[]);}catch(error){setError(error.message||'Could not load shift confirmation requests.');}finally{setLoaded(true);}}
 useEffect(()=>{load();},[]);
 async function respond(item,decision){
  if(decision==='confirm'&&item.invite_type==='automatic'&&!accepted[item.invite_id]){setError('Please review and accept the shift contract before confirming.');return;}
  setBusyId(item.invite_id);setError('');
  try{
   const result=await request('/shift-confirmations/'+item.invite_id+'/respond',{method:'POST',body:JSON.stringify({decision,contractAccepted:decision==='confirm'&&item.invite_type==='automatic'})});
   setItems(current=>current.filter(entry=>Number(entry.invite_id)!==Number(item.invite_id)));
   setNotice(decision==='confirm'?'Shift confirmed. You have been allocated this position.': 'You declined the shift invitation.');
   if(onRefresh)await onRefresh();
   if(result.status==='approved')window.dispatchEvent(new CustomEvent('hyrz:shift-confirmed'));
  }catch(error){setError(error.message||'Could not respond to this shift invitation.');await load();}
  finally{setBusyId(null);}
 }
 if(!loaded&&!items.length)return <section className="panel shift-confirmation-panel"><h2>Shift confirmations</h2><p>Loading confirmation requests…</p></section>;
 if(!items.length)return null;
 return <section className="panel shift-confirmation-panel"><span className="eyebrow">ACTION REQUIRED</span><h2>Confirm your shifts</h2><p>These positions are not yours until you confirm. For automatic matching, positions go to the first workers who confirm.</p>
 {items.map(item=><article className="shift-confirmation-card" key={item.invite_id}>
  <div className="shift-confirmation-card-heading"><div><strong>{item.title}</strong><small>{item.business_name}</small></div><span className="status pending">Awaiting confirmation</span></div>
  <div className="shift-confirmation-details"><span>{new Date(item.starts_at).toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'short'})}</span><span>{new Date(item.starts_at).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})} – {new Date(item.ends_at).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})}</span><span>{item.location}</span><strong>{money(item.hourly_pay)}/hr</strong></div>
  {item.invite_type==='automatic'&&<div className="shift-confirmation-contract"><strong>Shift contract</strong><p>{item.description||'Please review the shift details and requirements before accepting.'}</p><p><strong>Requirements:</strong> {Array.isArray(item.requirements)?item.requirements.join(', '):(typeof item.requirements==='string'?(()=>{try{return JSON.parse(item.requirements).join(', ')}catch{return 'As listed in the shift details'}})():'As listed in the shift details')}</p><p><strong>Preferences:</strong> {Array.isArray(item.preferences)?item.preferences.join(', '):(typeof item.preferences==='string'?(()=>{try{return JSON.parse(item.preferences).join(', ')}catch{return 'None specified'}})():'None specified')}</p><p><strong>Perks:</strong> {Array.isArray(item.perks)?item.perks.join(', '):(typeof item.perks==='string'?(()=>{try{return JSON.parse(item.perks).join(', ')}catch{return 'None specified'}})():'None specified')}</p><p><strong>Payment:</strong> Payment date shown on the employer invoice, up to 14 days. Hours worked must be recorded accurately and submitted for review.</p><label className="shift-confirmation-accept"><input type="checkbox" checked={Boolean(accepted[item.invite_id])} onChange={e=>setAccepted(current=>({...current,[item.invite_id]:e.target.checked}))}/><span>I have reviewed and agree to the shift contract.</span></label></div>}
  <div className="shift-confirmation-actions"><button type="button" className="primary" disabled={busyId!==null} onClick={()=>respond(item,'confirm')}>{busyId===item.invite_id?'Processing…':'Confirm shift'}</button><button type="button" className="secondary" disabled={busyId!==null} onClick={()=>respond(item,'decline')}>Decline</button></div>
 </article>)}
 </section>;
}

function WorkerTodaysShift({applications,checkouts,action,busy,onRefresh,setNotice}){
 const today=new Date();today.setHours(0,0,0,0);
 const todayKey=today.getFullYear()+'-'+String(today.getMonth()+1).padStart(2,'0')+'-'+String(today.getDate()).padStart(2,'0');
 const todays=(applications||[]).filter(a=>['approved','accepted','confirmed'].includes(String(a.status||'').toLowerCase())&&a.starts_at&&String(a.starts_at).slice(0,10)===todayKey).sort((a,b)=>new Date(a.starts_at)-new Date(b.starts_at));
 const scheduledShift=todays.find(a=>new Date(a.ends_at||a.starts_at)>=new Date())||todays[todays.length-1];
 const testCheckout=(checkouts||[]).filter(c=>Boolean(c.is_test)&&String(c.status||'').toLowerCase()==='open'&&c.actual_start&&String(c.actual_start).slice(0,10)===todayKey).sort((a,b)=>Number(b.id)-Number(a.id))[0];
 const shift=scheduledShift||(testCheckout?{id:testCheckout.shift_id,shift_id:testCheckout.shift_id,title:testCheckout.title||'Test shift',starts_at:testCheckout.actual_start,ends_at:testCheckout.actual_end,is_test:true}:null);
 const checkout=shift?(checkouts||[]).filter(c=>Number(c.shift_id)===Number(shift.shift_id||shift.shiftId||shift.id)&&String(c.status||'').toLowerCase()==='open').sort((a,b)=>Number(b.id)-Number(a.id))[0]:null;
 const clockedIn=Boolean(checkout?.clocked_in_at);
 const clockedOut=Boolean(checkout?.clocked_out_at);
 const refresh=async()=>{await onRefresh?.();};
 return <section className="stats worker-dashboard-stats worker-todays-shift-wrap"><article className="stat worker-dashboard-stat worker-todays-shift-card"><small>TODAY'S SHIFT</small>{shift?<><strong>{shift.title||shift.shift_title||'Confirmed shift'}</strong><span>{shift.starts_at?new Date(shift.starts_at).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'}):'Start time TBC'} – {shift.ends_at?new Date(shift.ends_at).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'}):'End time TBC'}</span><span>{shift.business_name||shift.employer_name||'Your confirmed shift'}</span>{checkout&&<span>Checkout #{checkout.id} · {clockedOut?'Clocked out':clockedIn?'Clocked in':'Not clocked in'}</span>}<div className="worker-todays-shift-actions">{!clockedIn?<button type="button" className="primary" disabled={busy} onClick={()=>action(async()=>{const result=await request('/checkouts/clock-in',{method:'POST',body:JSON.stringify({shiftId:Number(shift.shift_id||shift.shiftId||shift.id)})});setNotice('Clocked in successfully'+(result.checkoutId?' · Checkout #'+result.checkoutId:'')+'.');await refresh();})}>Clock in</button>:!clockedOut?<button type="button" className="primary" disabled={busy} onClick={()=>action(async()=>{await request('/checkouts/'+checkout.id+'/clock-out',{method:'POST',body:'{}'});setNotice('Clocked out successfully. Review your times in Open checkouts before submitting.');await refresh();})}>Clock out</button>:<span className="checkout-clock-complete">Clock-out recorded</span>}</div></>:<><strong>No shift scheduled today</strong><span>Your confirmed shifts will appear here on the day you work.</span></>}</article></section>;
}
function WorkerCheckoutControls({checkout,action,busy,onDone,setNotice}){
 const [editing,setEditing]=useState(false);
 const [actualStart,setActualStart]=useState(checkoutDateTimeLocal(checkout.actual_start));
 const [actualEnd,setActualEnd]=useState(checkoutDateTimeLocal(checkout.actual_end));
 const [breakMinutes,setBreakMinutes]=useState(String(checkout.break_minutes??0));
 const [reason,setReason]=useState('');
 useEffect(()=>{if(!editing){setActualStart(checkoutDateTimeLocal(checkout.actual_start));setActualEnd(checkoutDateTimeLocal(checkout.actual_end));setBreakMinutes(String(checkout.break_minutes??0));}},[checkout.actual_start,checkout.actual_end,checkout.break_minutes,editing]);
 return <div className="worker-checkout-controls"><button type="button" className="secondary" onClick={()=>setEditing(v=>!v)}>{editing?'Cancel time changes':'Review / adjust times'}</button>{editing&&<form onSubmit={e=>{e.preventDefault();action(async()=>{await request('/checkouts/'+checkout.id+'/submit',{method:'POST',body:JSON.stringify({actualStart,actualEnd,breakMinutes:Number(breakMinutes),reason})});setNotice('Checkout #'+checkout.id+' submitted for approval.');await onDone?.();});}}><label>Clock-in time<input type="datetime-local" required value={actualStart} onChange={e=>setActualStart(e.target.value)}/></label><label>Clock-out time<input type="datetime-local" required value={actualEnd} onChange={e=>setActualEnd(e.target.value)}/></label><label>Unpaid break (minutes)<input type="number" min="0" step="1" required value={breakMinutes} onChange={e=>setBreakMinutes(e.target.value)}/></label><label>Reason for changing times (required if either time differs)<textarea maxLength="2000" value={reason} onChange={e=>setReason(e.target.value)} placeholder="Explain why the recorded clock-in or clock-out time needs changing."/></label><button type="submit" className="primary" disabled={busy}>Send checkout for approval</button></form>}</div>;
}

function CounterOfferForm({checkout,action,busy,onDone,setNotice}) {
 const [open,setOpen]=useState(false);
 const [comment,setComment]=useState('');
 const [actualStart,setActualStart]=useState(String(checkout.actual_start||'').replace(' ','T').slice(0,16));
 const [actualEnd,setActualEnd]=useState(String(checkout.actual_end||'').replace(' ','T').slice(0,16));
 const [breakMinutes,setBreakMinutes]=useState(String(checkout.break_minutes??0));
 return <div className="counter-offer"><button type="button" className="secondary" onClick={()=>setOpen(v=>!v)}>{open?'Cancel counter-offer':'Dispute / counter-offer'}</button>{open&&<form onSubmit={e=>{e.preventDefault();action(async()=>{await request('/checkouts/'+checkout.id+'/counter-offer',{method:'POST',body:JSON.stringify({comment,actualStart:actualStart?actualStart.replace('T',' ')+':00':undefined,actualEnd:actualEnd?actualEnd.replace('T',' ')+':00':undefined,breakMinutes:Number(breakMinutes)})});setNotice('Counter-offer submitted for admin review.');setOpen(false);await onDone();});}}><label>Comment / reason<textarea required minLength="3" maxLength="3000" value={comment} onChange={e=>setComment(e.target.value)}/></label><label>Proposed start<input type="datetime-local" required value={actualStart} onChange={e=>setActualStart(e.target.value)}/></label><label>Proposed end<input type="datetime-local" required value={actualEnd} onChange={e=>setActualEnd(e.target.value)}/></label><label>Proposed break minutes<input type="number" min="0" required value={breakMinutes} onChange={e=>setBreakMinutes(e.target.value)}/></label><button className="primary" disabled={busy}>Submit counter-offer</button></form>}</div>;
}
